def tally(words: list[str]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    return counts

def busiest(counts: dict[str, int]) -> tuple[str, int]:
    best = max(counts, key=lambda k: counts[k])
    return best, counts[best]

trees = ["ash", "elm", "ash", "oak", "ash"]
print(tally(trees))
print(busiest(tally(trees)))

