from typing import Protocol, runtime_checkable

@runtime_checkable
class HasArea(Protocol):
    def area(self) -> float: ...

class Square:
    def __init__(self, side: float) -> None:
        self.side = side

    def area(self) -> float:
        return self.side * self.side

def total_area(items: list[object]) -> float:
    total = 0.0
    for item in items:
        if isinstance(item, HasArea):
            total += item.area()
    return total

