def ratios(pairs: list[list[float]]) -> list[float | None]:
    out: list[float | None] = []
    for top, bottom in pairs:
        if bottom == 0:
            out.append(None)
        else:
            out.append(top / bottom)
    return out

def group_by_initial(words: list[str]) -> dict[str, list[str]]:
    groups: dict[str, list[str]] = {}
    for word in words:
        if not word:
            continue
        letter = word[0].lower()
        groups.setdefault(letter, []).append(word)
    return groups

