def parse_scores(rows: list[list[str]]) -> dict[str, int]:
    scores: dict[str, int] = {}
    for name, text in rows:
        try:
            value = int(text)
        except ValueError:
            raise ValueError("bad score for " + name + ": " + text)
        scores[name] = value
    return scores

